<?php
define('ALLOWED_ACCESS',true);
require_once __DIR__.'/../../includes/paths.php';require_once $project_root.'includes/session.php';require_once $project_root.'languages/language.php';require_once $project_root.'includes/forever.php';
$public=forever_public_realms();$scope=(string)($_GET['realm']??'all');$q=mb_substr(trim((string)($_GET['search']??'')),0,64);$selected=[];
foreach($public as $realm)if($scope==='all'||(string)$realm['id']===$scope)$selected[]=$realm;if(!$selected&&$public)$selected=[$public[0]];
$players=[];$unavailable=[];$limit=100;
foreach($selected as $realm){$db=forever_char_db((int)$realm['id']);if(!$db){$unavailable[]=$realm['name'];continue;}$where=$q!==''?' AND c.name LIKE ?':'';
    $st=$db->prepare('SELECT c.guid,c.name,c.race,c.class,c.gender,c.level,c.online,g.name guild_name FROM characters c LEFT JOIN guild_member gm ON gm.guid=c.guid LEFT JOIN guild g ON g.guildid=gm.guildid WHERE c.deleteInfos_Account IS NULL'.$where.' ORDER BY c.online DESC,c.level DESC,c.name LIMIT 100');
    if(!$st){$unavailable[]=$realm['name'];continue;}if($q!==''){$like='%'.addcslashes($q,'%_\\').'%';$st->bind_param('s',$like);}$st->execute();foreach($st->get_result()->fetch_all(MYSQLI_ASSOC) as $row){$row['realm_id']=$realm['id'];$row['realm_name']=$realm['name'];$players[]=$row;}$st->close();
}
usort($players,static fn($a,$b)=>(int)$b['online']<=>(int)$a['online']?:(int)$b['level']<=>(int)$a['level']?:strcasecmp($a['name'],$b['name']));$more=count($players)>$limit;$players=array_slice($players,0,$limit);
$icons=[1=>'warrior',2=>'paladin',3=>'hunter',4=>'rogue',5=>'priest',7=>'shaman',8=>'mage',9=>'warlock',11=>'druid'];$colors=[1=>'#c79c6e',2=>'#f58cba',3=>'#abd473',4=>'#fff569',5=>'#fff',7=>'#0070de',8=>'#69ccf0',9=>'#9482c9',11=>'#ff7d0a'];
$page_class='armory-search';$page_title=translate('nav_armory','Armory');$page_head='<link rel="stylesheet" href="/assets/css/creator-studio.css"><style>.armory-directory{max-width:1250px;margin:40px auto;padding:24px}.armory-results{display:grid;grid-template-columns:repeat(auto-fill,minmax(270px,1fr));gap:14px;margin-top:24px}.armory-person{display:flex;align-items:center;gap:16px;padding:20px;background:#0c131eeb;border:1px solid #324052;border-left:3px solid var(--class-color);color:#d6e0ed;transition:150ms}.armory-person:hover{transform:translateY(-2px);border-color:#c7a961}.armory-person img{width:48px;height:48px;object-fit:cover;border:1px solid #8d7747}.armory-person strong{font-size:17px;color:var(--class-color)}.armory-person p{font-size:12px;color:#8496af;margin:4px 0}.armory-person .status{font-size:10px;color:#7ad2a0}.armory-person .offline{color:#8391a3}</style>';
include $project_root.'includes/header.php';$h=static fn($s)=>htmlspecialchars((string)$s,ENT_QUOTES,'UTF-8');
?>
<main class="armory-directory"><header class="studio-heading"><div><span class="studio-eyebrow">CHARACTER DIRECTORY</span><h1><?php echo translate('nav_armory','Armory'); ?></h1><p><?php echo translate('armory_search_intro','Find any character on the public realms, online or offline. Open a profile to inspect equipment, talents and spells.'); ?></p></div><a href="/armory/solo_pvp" class="studio-button"><?php echo translate('armory_pvp_rankings','PvP rankings'); ?></a></header>
<form class="studio-toolbar" method="get" action="/armory/"><label class="grow"><?php echo translate('armory_character_name','Character name'); ?><input name="search" id="armorySearch" maxlength="64" placeholder="<?php echo $h(translate('armory_search_placeholder','Search characters…')); ?>" value="<?php echo $h($q); ?>"></label><label><?php echo translate('realm','Realm'); ?><select name="realm"><option value="all" <?php echo $scope==='all'?'selected':''; ?>><?php echo translate('armory_all_realms','All public realms'); ?></option><?php foreach($public as $r):?><option value="<?php echo (int)$r['id']; ?>" <?php echo $scope===(string)$r['id']?'selected':''; ?>><?php echo $h($r['name']); ?></option><?php endforeach;?></select></label><button class="studio-button primary" type="submit"><?php echo translate('search','Search'); ?></button></form>
<?php if($unavailable):?><p class="studio-help"><?php echo translate('armory_realm_unavailable','Some realm databases are currently unavailable.'); ?></p><?php endif;?>
<p class="studio-help"><?php echo count($players).' '.translate('armory_matches','characters shown'); ?><?php echo $more?' · '.translate('armory_refine','Refine your search to see more results.'):''; ?></p><div class="armory-results">
<?php foreach($players as $p):?><a class="armory-person" style="--class-color:<?php echo $colors[(int)$p['class']]??'#c7a961'; ?>" href="/character?guid=<?php echo (int)$p['guid']; ?>&amp;realm=<?php echo (int)$p['realm_id']; ?>"><img src="/img/accountimg/class/<?php echo $icons[(int)$p['class']]??'warrior'; ?>.webp" alt="" loading="lazy"><div><strong><?php echo $h($p['name']); ?></strong><p><?php echo translate('level','Level').' '.(int)$p['level'].' · '.$h($p['realm_name']); ?></p><?php if($p['guild_name']):?><p>&lt;<?php echo $h($p['guild_name']); ?>&gt;</p><?php endif;?><span class="status <?php echo $p['online']?'':'offline'; ?>"><?php echo $p['online']?translate('online','Online'):translate('offline','Offline'); ?></span></div></a><?php endforeach;?></div>
<?php if(!$players):?><div class="creator-panel"><p><?php echo translate('armory_no_characters','No characters match your search. Try another name or realm.'); ?></p></div><?php endif;?></main>
